// MXShader.swift
//
// A Metal shader generated by MaterialX for one element of a document
// (spike M0c, docs/spikes/M0c-msl-swatch.md). The MSL source is compiled and
// drawn by PreviewKit; MXKit only produces it.
//
// Introduces (SWIFT): nested types, `Array(...)` from a C++ vector,
// `first(where:)`.

import MXBridge

/// One shader parameter, with its default value from the document.
public struct MXShaderUniform: Hashable, Sendable {
    /// The variable name in the generated source, such as "noise3d_amplitude".
    public let name: String
    /// The MaterialX type: "float", "color3", "matrix44", "filename", ...
    public let type: String
    /// The default value as numbers (3 for a color3, 16 for a matrix44).
    /// Empty if the renderer must provide the value (transforms, for example).
    public let value: [Float]
    /// The default value of a "filename" or "string" uniform.
    public let stringValue: String
}

/// A Metal shader generated by MaterialX.
public struct MXGeneratedShader: Sendable {
    /// MSL source of the vertex stage. Its entry point is `VertexMain`.
    public let vertexSource: String
    /// MSL source of the fragment stage. Its entry point is `FragmentMain`.
    public let pixelSource: String
    /// The MaterialX type of what is shaded: "color3", "float",
    /// "surfaceshader", "material", ...
    public let outputType: String
    /// The parameters of both stages.
    public let uniforms: [MXShaderUniform]

    /// The uniform called `name`, or nil.
    ///
    /// SWIFT: `first(where:)` returns the first element for which the
    /// closure returns true, as an optional (nil if there is none). The
    /// closure's `$0` is each uniform in turn.
    public func uniform(named name: String) -> MXShaderUniform? {
        uniforms.first(where: { $0.name == name })
    }

    /// Converts the bridge's C++ struct.
    ///
    /// SWIFT: `init(_:)` with no argument label, and `internal` (the default),
    /// so only MXKit can create one from the C++ type.
    init(_ shader: mxbridge.GeneratedShader) {
        vertexSource = shader.vertexSource.swiftString
        pixelSource = shader.pixelSource.swiftString
        outputType = shader.outputType.swiftString

        var uniforms: [MXShaderUniform] = []
        for uniform in shader.uniforms {
            uniforms.append(MXShaderUniform(
                name: uniform.name.swiftString,
                type: uniform.type.swiftString,
                // SWIFT: `Array(...)` copies the C++ std::vector<float> into a
                // Swift array of Float. C++ `float` and Swift `Float` are the
                // same 32-bit type, so no conversion of the numbers is needed.
                value: Array(uniform.value),
                stringValue: uniform.stringValue.swiftString
            ))
        }
        self.uniforms = uniforms
    }
}
